static const long long idx_ihi_[8]  = {4,12,5,13,6,14,7,15};

static inline __attribute__((always_inline)) void tr8(__m512d* r){
    __m512d t0 = _mm512_unpacklo_pd(r[0], r[1]);
    __m512d t1 = _mm512_unpackhi_pd(r[0], r[1]);
    __m512d t2 = _mm512_unpacklo_pd(r[2], r[3]);
    __m512d t3 = _mm512_unpackhi_pd(r[2], r[3]);
    __m512d t4 = _mm512_unpacklo_pd(r[4], r[5]);
    __m512d t5 = _mm512_unpackhi_pd(r[4], r[5]);
    __m512d t6 = _mm512_unpacklo_pd(r[6], r[7]);
    __m512d t7 = _mm512_unpackhi_pd(r[6], r[7]);
    __m512d u0 = _mm512_shuffle_f64x2(t0, t2, 0x88);
    __m512d u1 = _mm512_shuffle_f64x2(t1, t3, 0x88);
    __m512d u2 = _mm512_shuffle_f64x2(t0, t2, 0xDD);
    __m512d u3 = _mm512_shuffle_f64x2(t1, t3, 0xDD);
    __m512d u4 = _mm512_shuffle_f64x2(t4, t6, 0x88);
    __m512d u5 = _mm512_shuffle_f64x2(t5, t7, 0x88);
    __m512d u6 = _mm512_shuffle_f64x2(t4, t6, 0xDD);
    __m512d u7 = _mm512_shuffle_f64x2(t5, t7, 0xDD);
    r[0] = _mm512_shuffle_f64x2(u0, u4, 0x88);
    r[1] = _mm512_shuffle_f64x2(u1, u5, 0x88);
    r[2] = _mm512_shuffle_f64x2(u2, u6, 0x88);
    r[3] = _mm512_shuffle_f64x2(u3, u7, 0x88);
    r[4] = _mm512_shuffle_f64x2(u0, u4, 0xDD);
    r[5] = _mm512_shuffle_f64x2(u1, u5, 0xDD);
    r[6] = _mm512_shuffle_f64x2(u2, u6, 0xDD);
    r[7] = _mm512_shuffle_f64x2(u3, u7, 0xDD);
}
#define TR8(r) tr8(r)

static inline __attribute__((always_inline)) __m512d ld4s(const double* p0, const double* p1, const double* p2, const double* p3){
    __m256d a = _mm256_insertf128_pd(_mm256_castpd128_pd256(_mm_loadu_pd(p0)), _mm_loadu_pd(p1), 1);
    __m256d b = _mm256_insertf128_pd(_mm256_castpd128_pd256(_mm_loadu_pd(p2)), _mm_loadu_pd(p3), 1);
    return _mm512_insertf64x4(_mm512_castpd256_pd512(a), b, 1);
}
static inline __attribute__((always_inline)) void st4s(double* p0, double* p1, double* p2, double* p3, __m512d v){
    __m256d a = _mm512_castpd512_pd256(v);
    __m256d b = _mm512_extractf64x4_pd(v, 1);
    _mm_storeu_pd(p0, _mm256_castpd256_pd128(a));
    _mm_storeu_pd(p1, _mm256_extractf128_pd(a, 1));
    _mm_storeu_pd(p2, _mm256_castpd256_pd128(b));
    _mm_storeu_pd(p3, _mm256_extractf128_pd(b, 1));
}
static inline __attribute__((always_inline)) __m256d ld2s(const double* p0, const double* p1){
    return _mm256_insertf128_pd(_mm256_castpd128_pd256(_mm_loadu_pd(p0)), _mm_loadu_pd(p1), 1);
}
static inline __attribute__((always_inline)) void st2s(double* p0, double* p1, __m256d v){
    _mm_storeu_pd(p0, _mm256_castpd256_pd128(v));
    _mm_storeu_pd(p1, _mm256_extractf128_pd(v, 1));
}


